// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // Admissible domain: owner is the deployer (this test contract); amount must be a
        // transferable positive amount covered by the contract's balance.
        vm.deal(address(c), 1 ether);
        vm.assume(actor == address(this));
        amount = bound(amount, 1, 1 ether);

        // Adversarial counterparty: reverts unless it is given far more than the
        // 2300-gas stipend a `transfer` forwards (a low-level `call` forwards all gas).
        GasSniffer sniffer = new GasSniffer();

        vm.prank(actor);
        bool ok;
        try c.sendTo(address(sniffer), amount) { ok = true; } catch { ok = false; }

        // General rule: sendTo must NOT report success when the receiver rejects funds
        // (revert through the 2300-gas path). Reference C always reverts here (ok == false
        // for every admissible amount); the mutant's unchecked low-level call delivers all
        // gas, the receiver accepts, and sendTo reports success (ok == true).
        assertTrue(!ok, "sendTo must fail when receiver rejects the transfer");
    }
}

contract GasSniffer {
    fallback() external payable {
        // A `transfer` hands us ~2300 gas; a low-level `call` hands us the whole remaining gas.
        if (gasleft() < 50000) {
            revert();
        }
    }
}

